/** Stickers are die-cut: a white edge around the drawing. The rest are badges, framed by their tier. */
fun isSticker(badge: Badge): Boolean = badge in stickers

private val stickers = setOf(Badge.DID_SOME, Badge.HALFWAY, Badge.FULL_ENOUGH, Badge.TWO_IN_A_ROW, Badge.CROWNED, Badge.BACK_AT_IT, Badge.MILESTONE, Badge.STRONG_START, Badge.SHOWED_UP, Badge.WEEKEND_WARRIOR, Badge.RECHARGING_DAY, Badge.RESTED, Badge.GENTLE_WIN, Badge.FIRST_ONE, Badge.SECOND_CHANCE, Badge.HAT_TRICK, Badge.COUNT_IT, Badge.HEAVY_LIFTING, Badge.OVERDUE_NO_MORE, Badge.FELT_HAPPY, Badge.FELT_SAD, Badge.FELT_ANGRY, Badge.FELT_DREAMY, Badge.FELT_BORED, Badge.FELT_UNWELL, Badge.DRANK_UP, Badge.ALL_FOUR)

/** A badge's whole picture, on a 52-unit grid. A sticker's includes its white edge. Built once, on first use. */
fun badgeArt(badge: Badge): ImageVector = art.getValue(badge)

/** A sticker's outline, for its shadow, or null for a badge, whose frame draws its own. */
fun badgeOutline(badge: Badge): ImageVector? = outlines[badge]

private val art: Map<Badge, ImageVector> by lazy {
    Badge.entries.associateWith { badge ->
        vector { if (badge in stickers) { draw(badge, Layer.EDGE); draw(badge, Layer.CUT) }; draw(badge, Layer.ART) }
    }
}

/** How many water glasses there are to mix along the diary's water row. */
const val WATER_GLASSES = 6

/** Water glass [variant] as a sticker, white edge and all, and its outline for the shadow. */
fun waterGlassArt(variant: Int): ImageVector = glassArt.getValue(variant)
fun waterGlassOutline(variant: Int): ImageVector = glassOutlines.getValue(variant)

/** Water glass [variant] as black lines, like [badgeLines]. */
fun waterGlassLines(variant: Int): ImageVector = glassLines.getOrPut(variant) { vector { drawGlass(variant, Layer.LINE) } }

private val glassArt: Map<Int, ImageVector> by lazy {
    (0 until WATER_GLASSES).associateWith { vector { drawGlass(it, Layer.EDGE); drawGlass(it, Layer.CUT); drawGlass(it, Layer.ART) } }
}
private val glassOutlines: Map<Int, ImageVector> by lazy {
    (0 until WATER_GLASSES).associateWith { vector { drawGlass(it, Layer.EDGE) } }
}
private val glassLines = mutableMapOf<Int, ImageVector>()

private fun Pen.drawGlass(variant: Int, layer: Layer) {
    val pen = Pen(builder, layer)
    when (variant) {
        0 -> pen.glass0()
        1 -> pen.glass1()
        2 -> pen.glass2()
        3 -> pen.glass3()
        4 -> pen.glass4()
        5 -> pen.glass5()
    }
}

/**
 * A day factor ("guests", DayFactors' icon names) as a sticker, its outline for the shadow, and its black
 * lines. Null for a name with no drawing.
 */
fun dayFactorArt(icon: String): ImageVector? = factorArt[icon]
fun dayFactorOutline(icon: String): ImageVector? = factorOutlines[icon]
fun dayFactorLines(icon: String): ImageVector? =
    if (icon in factorIcons) factorLines.getOrPut(icon) { vector { drawFactor(icon, Layer.LINE) } } else null

/** "sleeping" is no day factor to pick; it is the sticker for a past day with nothing on it. */
private val factorIcons = setOf("guests", "weather", "work", "errand", "travel", "family", "home", "sleeping")
private val factorArt: Map<String, ImageVector> by lazy {
    factorIcons.associateWith { vector { drawFactor(it, Layer.EDGE); drawFactor(it, Layer.CUT); drawFactor(it, Layer.ART) } }
}
private val factorOutlines: Map<String, ImageVector> by lazy {
    factorIcons.associateWith { vector { drawFactor(it, Layer.EDGE) } }
}
private val factorLines = mutableMapOf<String, ImageVector>()

private fun Pen.drawFactor(icon: String, layer: Layer) {
    val pen = Pen(builder, layer)
    when (icon) {
        "guests" -> pen.factorGuests()
        "weather" -> pen.factorWeather()
        "work" -> pen.factorWork()
        "errand" -> pen.factorErrand()
        "travel" -> pen.factorTravel()
        "family" -> pen.factorFamily()
        "home" -> pen.factorHome()
        "sleeping" -> pen.factorSleeping()
    }
}

private val outlines: Map<Badge, ImageVector> by lazy {
    stickers.associateWith { badge -> vector { draw(badge, Layer.EDGE) } }
}

/**
 * A badge's drawing as plain black lines, a little uneven as if drawn by hand: its outlines and its ink,
 * without colour, highlights or a sticker's edge. Tint it to taste.
 */
fun badgeLines(badge: Badge): ImageVector = lines.getOrPut(badge) { vector { draw(badge, Layer.LINE) } }

private val lines = mutableMapOf<Badge, ImageVector>()

/**
 * The drawing itself, then a sticker's white cut and its darker rim, each the drawing with a wide stroke.
 * LINE is the drawing in black lines only.
 */
private enum class Layer { ART, CUT, EDGE, LINE }

private class Pen(val builder: ImageVector.Builder, val layer: Layer) {
    /** Seeds each path's wobble, so a line drawing comes out the same every time. */
    var paths = 0
}

private const val Ink = 0xFF3A2A20
private val LineColor = SolidColor(Color.Black)

private val EdgeColor = SolidColor(Color(0xFFE3D8C6))
private val CutColor = SolidColor(Color.White)

private fun vector(paint: Pen.() -> Unit): ImageVector =
    ImageVector.Builder(defaultWidth = 52.dp, defaultHeight = 52.dp, viewportWidth = 52f, viewportHeight = 52f)
        .apply { group(translationX = 2f, translationY = 2f) { Pen(this, Layer.ART).paint() } }
        .build()

private fun Pen.draw(badge: Badge, layer: Layer) {
    val pen = Pen(builder, layer)
    when (badge) {
        Badge.DID_SOME -> pen.didSome()
        Badge.HALFWAY -> pen.halfway()
        Badge.FULL_ENOUGH -> pen.fullEnough()
        Badge.CLEAN_SWEEP -> pen.cleanSweep()
        Badge.TWO_IN_A_ROW -> pen.twoInARow()
        Badge.SEVEN_DAY_RUN -> pen.sevenDayRun()
        Badge.THIRTY_DAY_RUN -> pen.thirtyDayRun()
        Badge.CROWNED -> pen.crowned()
        Badge.ALL_THREE_CROWNS -> pen.allThreeCrowns()
        Badge.CONQUEROR -> pen.conqueror()
        Badge.BACK_AT_IT -> pen.backAtIt()
        Badge.THE_RETURN -> pen.theReturn()
        Badge.RE_RETURN -> pen.reReturn()
        Badge.MILESTONE -> pen.milestone()
        Badge.FINISH_LINE -> pen.finishLine()
        Badge.PERSONAL_BEST -> pen.personalBest()
        Badge.STRONG_START -> pen.strongStart()
        Badge.SHOWED_UP -> pen.showedUp()
        Badge.WEEKEND_WARRIOR -> pen.weekendWarrior()
        Badge.RECHARGING_DAY -> pen.rechargingDay()
        Badge.RESTED -> pen.rested()
        Badge.GENTLE_WIN -> pen.gentleWin()
        Badge.FIRST_ONE -> pen.firstOne()
        Badge.SECOND_CHANCE -> pen.secondChance()
        Badge.HAT_TRICK -> pen.hatTrick()
        Badge.COUNT_IT -> pen.countIt()
        Badge.HEAVY_LIFTING -> pen.heavyLifting()
        Badge.OVERDUE_NO_MORE -> pen.overdueNoMore()
        Badge.FELT_HAPPY -> pen.feltHappy()
        Badge.FELT_SAD -> pen.feltSad()
        Badge.FELT_ANGRY -> pen.feltAngry()
        Badge.FELT_DREAMY -> pen.feltDreamy()
        Badge.FELT_BORED -> pen.feltBored()
        Badge.FELT_UNWELL -> pen.feltUnwell()
        Badge.DRANK_UP -> pen.drankUp()
        Badge.ALL_FOUR -> pen.allFour()
        Badge.PILLAR_FILLED -> pen.pillarFilled()
    }
}

private fun Pen.p(d: String, fill: Long?, stroke: Long?, width: Float, alpha: Float = 1f) {
    val nodes = addPathNodes(d)
    when (layer) {
        Layer.ART -> builder.addPath(
            nodes,
            fill = fill?.let { SolidColor(Color(it)) }, fillAlpha = alpha,
            stroke = stroke?.let { SolidColor(Color(it)) }, strokeAlpha = alpha, strokeLineWidth = width,
            strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round,
        )
        Layer.CUT -> builder.addPath(nodes, fill = CutColor, stroke = CutColor, strokeLineWidth = 6f, strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round)
        Layer.EDGE -> builder.addPath(nodes, fill = EdgeColor, stroke = EdgeColor, strokeLineWidth = 7.2f, strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round)
        Layer.LINE -> {
            // Ink fills (eyes, pupils) stay solid; coloured fills, white marks and faint ones go.
            val solid = fill == Ink
            val line = stroke != null && stroke != 0xFFFFFFFF && alpha == 1f
            if (!solid && !line) return
            builder.addPath(
                wobble(nodes),
                fill = if (solid) LineColor else null,
                stroke = if (line) LineColor else null, strokeLineWidth = width * 1.1f,
                strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round,
            )
        }
    }
}

/** Nudges every point by up to half a unit, and a round's radii by a few percent, so lines look hand drawn. */
private fun Pen.wobble(nodes: List<PathNode>): List<PathNode> {
    val random = Random(++paths * 7919)
    fun j() = (random.nextFloat() - 0.5f)
    return nodes.map { n ->
        when (n) {
            is PathNode.MoveTo -> n.copy(x = n.x + j(), y = n.y + j())
            is PathNode.LineTo -> n.copy(x = n.x + j(), y = n.y + j())
            is PathNode.RelativeLineTo -> n.copy(dx = n.dx + j(), dy = n.dy + j())
            is PathNode.QuadTo -> n.copy(x1 = n.x1 + j(), y1 = n.y1 + j(), x2 = n.x2 + j(), y2 = n.y2 + j())
            is PathNode.RelativeQuadTo -> n.copy(dx1 = n.dx1 + j(), dy1 = n.dy1 + j(), dx2 = n.dx2 + j(), dy2 = n.dy2 + j())
            is PathNode.CurveTo -> n.copy(x1 = n.x1 + j(), y1 = n.y1 + j(), x2 = n.x2 + j(), y2 = n.y2 + j(), x3 = n.x3 + j(), y3 = n.y3 + j())
            is PathNode.RelativeCurveTo -> n.copy(dx1 = n.dx1 + j(), dy1 = n.dy1 + j(), dx2 = n.dx2 + j(), dy2 = n.dy2 + j(), dx3 = n.dx3 + j(), dy3 = n.dy3 + j())
            is PathNode.ArcTo -> n.copy(
                horizontalEllipseRadius = n.horizontalEllipseRadius * (1 + j() * 0.08f),
                verticalEllipseRadius = n.verticalEllipseRadius * (1 + j() * 0.08f),
                arcStartX = n.arcStartX + j(), arcStartY = n.arcStartY + j(),
            )
            is PathNode.RelativeArcTo -> n.copy(
                horizontalEllipseRadius = n.horizontalEllipseRadius * (1 + j() * 0.08f),
                verticalEllipseRadius = n.verticalEllipseRadius * (1 + j() * 0.08f),
                arcStartDx = n.arcStartDx + j(), arcStartDy = n.arcStartDy + j(),
            )
            else -> n
        }
    }
}

private inline fun Pen.g(tx: Float, ty: Float, scale: Float, rotate: Float, crossinline paint: Pen.() -> Unit) {
    val pen = this
    builder.group(rotate = rotate, scaleX = scale, scaleY = scale, translationX = tx, translationY = ty) { pen.paint() }
}

